import type { Session } from '@supabase/supabase-js';
import { pressEnterInChrome, pressKeyInChrome } from './keyboard';

type Fixture = {
  organizationId: string;
  classroomId: string;
  studentId: string;
  signalId: string;
  asOf: string;
};
type Context = Fixture & { teacher: Session };
type Snapshot = {
  attempts: string;
  episodes: string;
  reviews: number;
  audits: number;
  review: { reviewed_by: string; reviewed_at: string } | null;
};
type Measurement = {
  concurrency: 1 | 4;
  firstReviewMs: number | null;
  firstSignalId: string | null;
  samples: { signalId: string; durationMs: number; valid: boolean }[];
  startedAt: number | null;
  signalId: string;
  index: number;
  background?: unknown;
};
let measurement: Measurement | null = null;
const el = (name: string) => `[data-cy="signal-review-${name}"]`;
function prepare() {
  return cy
    .task<Fixture>('signal-review:prepare', {}, { log: false, timeout: 180000 })
    .then((c) =>
      cy
        .task<Session>('identity:login', 'TEACHER', { log: false })
        .then((teacher) => ({ ...c, teacher })),
    );
}
function path(c: Fixture, detail = false) {
  return detail
    ? `/clases/${c.classroomId}/estudiantes/${c.studentId}?asOf=${encodeURIComponent(c.asOf)}`
    : `/clases/${c.classroomId}/tablero?asOf=${encodeURIComponent(c.asOf)}`;
}
function visit(
  c: Context,
  detail = false,
  beforeLoad?: (window: Cypress.AUTWindow) => void,
) {
  cy.visit(path(c, detail), {
    onBeforeLoad(window) {
      window.localStorage.setItem(
        'alunza.auth.127.0.0.1:18421',
        JSON.stringify(c.teacher),
      );
      beforeLoad?.(window);
    },
  });
}
function open(c: Fixture, detail = false) {
  const prefix = detail ? 'student-detail' : 'dashboard';
  cy.get(`[data-cy="${prefix}-signal-row"][data-signal-id="${c.signalId}"]`)
    .find(`[data-cy="${prefix}-open-signal"]`)
    .click();
  cy.get(el('open')).should('be.visible').click();
  cy.get(el('confirmation')).should('be.visible');
}
function snapshot(c: Fixture) {
  return cy.task<Snapshot>('signal-review:snapshot', c, { log: false });
}
function confirm() {
  cy.get(el('confirm')).click();
  cy.get(el('confirmed'))
    .should('be.visible')
    .and('contain.text', 'Responsable:');
}
function unchangedEvidence(before: Snapshot, after: Snapshot) {
  expect(after.attempts).to.equal(before.attempts);
  expect(after.episodes).to.equal(before.episodes);
}

describe('IMP-06.04 · Revisión docente confirmada', () => {
  afterEach(function () {
    const draft = measurement;
    measurement = null;
    cy.task('signal-review:loadStop', null, {
      log: false,
      timeout: 60000,
    }).then((background) => {
      if (draft && this.currentTest?.state === 'failed') {
        draft.background = background;
        if (draft.startedAt !== null && draft.index > 0)
          draft.samples.push({
            signalId: draft.signalId,
            durationMs: performance.now() - draft.startedAt,
            valid: false,
          });
        cy.task('signal-review:performance', draft, { log: false });
      }
    });
    cy.task('foundation:apiStart', null, { log: false });
  });
  it('IMP06-REVIEW-01 · Cancelar y confirmar desde tablero → ninguna escritura al cancelar y una revisión persistida', () => {
    prepare().then((c) =>
      snapshot(c).then((before) => {
        let writes = 0;
        cy.intercept('PUT', `**/signals/${c.signalId}/review`, (request) => {
          writes++;
          request.continue();
        }).as('review');
        visit(c);
        open(c);
        cy.get(el('cancel')).click();
        cy.get(el('confirmation')).should('not.exist');
        cy.get(el('open')).should('be.focused');
        cy.get(el('open')).click();
        pressKeyInChrome('Escape');
        cy.get(el('confirmation')).should('not.exist');
        snapshot(c).then((after) => expect(after).to.deep.equal(before));
        cy.then(() => expect(writes).to.equal(0));
        cy.get(el('open')).click();
        confirm();
        cy.wait('@review').its('response.statusCode').should('equal', 200);
        snapshot(c).then((after) => {
          unchangedEvidence(before, after);
          expect(after.reviews).to.equal(before.reviews + 1);
          expect(after.audits).to.equal(before.audits + 1);
          expect(after.review?.reviewed_by).to.equal(c.teacher.user.id);
        });
        cy.location('search').should('contain', encodeURIComponent(c.asOf));
        cy.get(el('present')).click();
        cy.get(el('confirmation')).should('not.exist');
        cy.get(
          `[data-cy="dashboard-signal-row"][data-signal-id="${c.signalId}"]`,
        ).should('not.exist');
        cy.get('#signals-state').select('REVIEWED');
        cy.contains('button', 'Filtrar señales').click();
        cy.get(`[data-signal-id="${c.signalId}"]`).should(
          'contain.text',
          'Responsable:',
        );
      }),
    );
  });
  it('IMP06-REVIEW-02 · Confirmar desde detalle y repetir → conserva responsable, fecha y evidencia', () => {
    prepare().then((c) =>
      snapshot(c).then((before) => {
        let writes = 0;
        cy.intercept('PUT', `**/signals/${c.signalId}/review`, (request) => {
          writes++;
          request.continue();
        });
        visit(c, true);
        open(c, true);
        cy.get(el('confirm')).dblclick();
        cy.get(el('confirmed')).should('be.visible');
        cy.then(() => expect(writes).to.equal(1));
        snapshot(c).then((after) => {
          unchangedEvidence(before, after);
          cy.task('signal-review:review', c, { log: false })
            .its('status')
            .should('equal', 200);
          snapshot(c).then((again) => expect(again).to.deep.equal(after));
        });
        cy.get(el('present')).click();
        cy.get('[data-cy="student-detail-ready"]').should('be.visible');
        cy.location('search').should('not.contain', encodeURIComponent(c.asOf));
        cy.get(
          `[data-cy="student-detail-signal-row"][data-signal-id="${c.signalId}"]`,
        ).should('not.exist');
      }),
    );
  });
  it('IMP06-REVIEW-03 · Confirmar una vista anterior ya revisada → recupera la primera revisión sin reescribir el corte', () => {
    prepare().then((c) => {
      visit(c);
      open(c);
      cy.task('signal-review:review', c, { log: false })
        .its('status')
        .should('equal', 200);
      snapshot(c).then((first) => {
        confirm();
        cy.get(el('confirmed')).should(
          'have.attr',
          'data-reviewed-at',
          first.review!.reviewed_at,
        );
        snapshot(c).then((after) => expect(after).to.deep.equal(first));
        cy.task<{
          data: { signal: { state: string; reviewedBy: string | null } };
        }>(
          'signal-review:query',
          { ...c, historical: true },
          { log: false },
        ).then(({ data }) => {
          expect(data.signal.state).to.equal('ACTIVE');
          expect(data.signal.reviewedBy).to.equal(null);
        });
        cy.task<{ data: { signal: { state: string } } }>(
          'signal-review:query',
          c,
          { log: false },
        )
          .its('data.signal.state')
          .should('equal', 'REVIEWED');
      });
    });
  });
  it('IMP06-REVIEW-04 · Perder acceso antes de confirmar → rechazo seguro y contenido retirado', () => {
    for (const actor of ['teacher', 'student'] as const) {
      prepare().then((c) =>
        snapshot(c).then((before) => {
          visit(c, true);
          open(c, true);
          cy.task('signal-review:revoke', { ...c, actor }, { log: false });
          cy.get(el('confirm')).click();
          cy.contains('Acceso no permitido').should('be.visible');
          cy.get('[data-cy="student-detail"]').should('not.exist');
          cy.get(el('confirmation')).should('not.exist');
          snapshot(c).then((after) => expect(after).to.deep.equal(before));
        }),
      );
    }
  });
  it('IMP06-REVIEW-05 · Perder una respuesta después del commit → comprobar recupera la revisión sin otro cambio', () => {
    prepare().then((c) => {
      let discarded = false,
        writes = 0;
      cy.intercept('PUT', `**/signals/${c.signalId}/review`, (request) => {
        writes++;
        request.continue();
      });
      visit(c, false, (window) => {
        const original = window.fetch.bind(window);
        window.fetch = (input, init) =>
          original(input, init).then((response) => {
            if (
              !discarded &&
              init?.method === 'PUT' &&
              String(input).endsWith(`/signals/${c.signalId}/review`) &&
              response.ok
            ) {
              discarded = true;
              throw new TypeError('Respuesta perdida después del commit TEST');
            }
            return response;
          });
      });
      open(c);
      cy.get(el('confirm')).click();
      cy.get(el('confirmation')).should(
        'contain.text',
        'todavía no está confirmado',
      );
      snapshot(c).then((first) => {
        expect(first.reviews).to.equal(1);
        cy.get(el('confirm'))
          .should('contain.text', 'Comprobar revisión')
          .click();
        cy.get(el('confirmed')).should(
          'have.attr',
          'data-reviewed-at',
          first.review!.reviewed_at,
        );
        snapshot(c).then((after) => expect(after).to.deep.equal(first));
      });
      cy.then(() => {
        expect(discarded).to.equal(true);
        expect(writes).to.equal(1);
      });
    });
  });
  it('IMP06-REVIEW-06 · Caída real de API antes del envío → error recuperable, ninguna revisión y confirmación posterior', () => {
    prepare().then((c) =>
      snapshot(c).then((before) => {
        visit(c);
        open(c);
        cy.task('foundation:apiStop', null, { log: false });
        cy.get(el('confirm')).click();
        cy.get(el('confirmation')).find('[role="alert"]').should('be.visible');
        cy.get(el('confirmed')).should('not.exist');
        snapshot(c).then((after) => expect(after).to.deep.equal(before));
        cy.task('foundation:apiStart', null, { log: false });
        cy.get(el('confirm'))
          .should('contain.text', 'Comprobar revisión')
          .click();
        cy.contains('La señal sigue pendiente de revisión.').should(
          'be.visible',
        );
        confirm();
      }),
    );
  });
  it('IMP06-REVIEW-07 · Teclado y pantallas responsivas → confirmación accesible; matrícula histórica y archivo solo consultables', () => {
    prepare().then((c) => {
      visit(c);
      for (const [size, width, height] of [
        ['desktop', 1440, 900],
        ['tablet', 768, 1024],
        ['mobile', 390, 844],
      ] as const) {
        cy.viewport(width, height);
        const trigger = `[data-signal-id="${c.signalId}"] [data-cy="dashboard-open-signal"]`;
        cy.get(trigger).focus().should('be.focused');
        pressEnterInChrome();
        cy.get(el('open')).focus().should('be.focused');
        pressEnterInChrome();
        cy.get(el('confirm')).should('be.focused');
        pressKeyInChrome('Tab');
        cy.get(el('cancel')).should('be.focused');
        cy.screenshot(`imp06-signal-review-${size}`, {
          capture: 'viewport',
          overwrite: true,
          log: false,
        });
        pressKeyInChrome('Escape');
        cy.get(el('open')).should('be.focused');
        pressKeyInChrome('Escape');
        cy.get(trigger).should('be.focused');
      }
      cy.task('signal-review:enrollment', c, { log: false });
      visit(c);
      cy.get(
        `[data-signal-id="${c.signalId}"] [data-cy="dashboard-open-signal"]`,
      ).click();
      cy.get('[data-cy="dashboard-signal-details"]').should(
        'contain.text',
        'matrícula activa',
      );
      cy.get(el('open')).should('not.exist');
      cy.task(
        'signal-review:enrollment',
        { ...c, restore: true },
        { log: false },
      );
      cy.task('signal-review:archive', c, { log: false });
      visit(c);
      cy.get(
        `[data-signal-id="${c.signalId}"] [data-cy="dashboard-open-signal"]`,
      ).click();
      cy.get(el('open')).should('not.exist');
      snapshot(c).then((after) => {
        expect(after.reviews).to.equal(0);
        expect(after.audits).to.equal(0);
      });
    });
  });
  it('IMP06-REVIEW-08 · Confirmar 50 episodios nuevos por perfil → REVIEWED renderizado bajo el objetivo local', () => {
    for (const concurrency of [1, 4] as const) {
      const draft: Measurement = {
        concurrency,
        firstReviewMs: null,
        firstSignalId: null,
        samples: [],
        startedAt: null,
        signalId: '',
        index: 0,
      };
      cy.task<Fixture[]>(
        'signal-review:batch',
        { count: 51 },
        { log: false, timeout: 600000 },
      ).then((items) => {
        expect(new Set(items.map((item) => item.signalId)).size).to.equal(51);
        cy.task<Session>('identity:login', 'TEACHER', { log: false }).then(
          (teacher) => {
            cy.then(() => {
              measurement = draft;
            });
            if (concurrency === 4)
              cy.task<{ workers: number }>('signal-review:loadStart', null, {
                log: false,
                timeout: 180000,
              })
                .its('workers')
                .should('equal', 3);
            items.forEach((item, index) => {
              const c = { ...item, teacher };
              visit(c);
              open(c);
              cy.then(() => {
                draft.startedAt = performance.now();
                draft.index = index;
                draft.signalId = c.signalId;
              });
              confirm();
              cy.window({ log: false }).then(
                (window) =>
                  new Promise<void>((resolve) =>
                    window.requestAnimationFrame(() =>
                      window.requestAnimationFrame(() => resolve()),
                    ),
                  ),
              );
              cy.then(() => {
                const durationMs = performance.now() - draft.startedAt!;
                draft.startedAt = null;
                if (index === 0) {
                  draft.firstReviewMs = durationMs;
                  draft.firstSignalId = c.signalId;
                } else
                  draft.samples.push({
                    signalId: c.signalId,
                    durationMs,
                    valid: true,
                  });
              });
            });
            cy.task('signal-review:loadStop', null, {
              log: false,
              timeout: 60000,
            }).then((background) => {
              draft.background = background;
            });
            cy.then(() =>
              cy.task<{ passed: boolean; samples: number; p95Ms: number }>(
                'signal-review:performance',
                draft,
                { log: false },
              ),
            ).then((result) => {
              expect(result.samples).to.equal(50);
              expect(result.p95Ms).to.be.lessThan(3000);
              expect(result.passed).to.equal(true);
              measurement = null;
            });
          },
        );
      });
    }
  });
});
